function makeGrid() { return new Uint8Array(ROWS * COLS); }
function idx(r, c) { return r * COLS + c; }

function countNeighbors(g, r, c) {
  let n = 0;
  for (let dr = -1; dr <= 1; dr++)
    for (let dc = -1; dc <= 1; dc++) {
      if (dr === 0 && dc === 0) continue;
      const nr = (r + dr + ROWS) % ROWS, nc = (c + dc + COLS) % COLS;
      n += g[idx(nr, nc)];
    }
  return n;
}

function step() {
  let pop = 0;
  for (let r = 0; r < ROWS; r++)
    for (let c = 0; c < COLS; c++) {
      const n = countNeighbors(grid, r, c);
      const alive = grid[idx(r, c)];
      const cell = alive ? (n === 2 || n === 3 ? 1 : 0) : (n === 3 ? 1 : 0);
      next[idx(r, c)] = cell;
      pop += cell;
