  document.getElementById('popCount').textContent = pop;
  draw();
}

function place(cells, or, oc) {
  cells.forEach(([r, c]) => {
    const nr = (or + r + ROWS) % ROWS, nc = (oc + c + COLS) % COLS;
    grid[idx(nr, nc)] = 1;
  });
  let pop = 0;
  for (let i = 0; i < grid.length; i++) pop += grid[i];
  document.getElementById('popCount').textContent = pop;
  draw();
