      [0,5,7,12],        // row 2
      [0,5,7,12],        // row 3
      [0,5,7,12],        // row 4
      [2,3,4,8,9,10],   // row 5
      [],                 // row 6
      [2,3,4,8,9,10],   // row 7
      [0,5,7,12],        // row 8
      [0,5,7,12],        // row 9
      [0,5,7,12],        // row 10
      [],                 // row 11
      [2,3,4,8,9,10],   // row 12
